(()=>{
 if(!window.JHONEME_SERVER)return;
 let revision=0,dirty=false,sending=null,blocked=false,ready=false,errorMessage='',label='Carregando banco…';
 const api={get ready(){return ready},get blocked(){return blocked},get label(){return label},get unsaved(){return dirty||!!sending},queue,showError};window.agencySync=api;
 function status(text){label=text;const el=document.querySelector('.saved');if(el)el.textContent=text}
 async function request(method,payload){const response=await fetch('/api/workspace',{method,credentials:'same-origin',headers:payload?{'Content-Type':'application/json'}:{},body:payload?JSON.stringify(payload):undefined});if(response.status===401)throw Error('Sua sessão terminou. Exporte as alterações pendentes e entre novamente.');if(response.status===409)throw Error('Outra aba ou dispositivo salvou uma versão mais recente. Exporte suas alterações antes de recarregar para comparar as duas versões.');if(!response.ok)throw Error('Não foi possível salvar no banco. Exporte as alterações pendentes antes de recarregar.');return response.json()}
 function showError(){document.getElementById('editor').close();document.getElementById('app').innerHTML=`<main class="sync-error"><span class="monogram">j.</span><h1>Vamos preservar seu trabalho.</h1><p>${esc(errorMessage)}</p><div class="actions">${ready?'<button class="btn primary" id="sync-export">Exportar esta versão</button>':''}<button class="btn" id="sync-reload">Recarregar agência</button></div><small>Os dados já salvos na VPS continuam no banco.</small></main>`;document.getElementById('sync-export')?.addEventListener('click',()=>download('jhoneme-alteracoes-pendentes.json',JSON.stringify(state,null,2),'application/json'));document.getElementById('sync-reload').addEventListener('click',()=>{if(!dirty||confirm('Você exportou as alterações pendentes? Recarregar descarta o que ainda não chegou ao banco.')){dirty=false;location.reload()}})}
 function queue(){if(!ready||blocked)return false;dirty=true;status('Salvando na VPS…');if(!sending){sending=Promise.resolve().then(drain).finally(()=>{sending=null})}return true}
 async function drain(){try{while(dirty&&!blocked){dirty=false;const snapshot=structuredClone(state);const result=await request('PUT',{state:snapshot,expectedRevision:revision});revision=result.revision}status('Salvo na VPS')}catch(err){dirty=true;blocked=true;errorMessage=err.message;status('Alterações pendentes');showError()}}
 document.addEventListener('click',async e=>{if(e.target.closest('[data-action="sign-out"]')){if(editorDirty&&!confirm('Sair descarta o formulário ainda não salvo. Continuar?'))return;if(sending)await sending;if(blocked||dirty)return;try{const res=await fetch('/api/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!res.ok)throw Error();location.replace('/login')}catch{toast('Não foi possível sair. Tente novamente.')}}});
 (async()=>{try{const data=await request('GET');revision=data.revision;if(data.state){if(!isState(data.state))throw Error('O banco contém uma versão incompatível. Preserve seu backup e confira a versão instalada.');state=data.state;if(!state.studio)state.studio=newStudio();ensureAdvisor(state.studio)}ready=true;label='Salvo na VPS';render();if(!data.state)queue()}catch(err){blocked=true;errorMessage=err.message;showError()}})();
})();
